// Regenerates the benchmark highlight blocks in the repo README and the core
// package README from the committed scorecard, and keeps docs.json's version
// variable aligned with the core pubspec.
//
// Usage (from anywhere):
//   dart tool/docs/sync_readme_benchmarks.dart            # write changes
//   dart tool/docs/sync_readme_benchmarks.dart --check    # fail on drift
//
// Blocks between `ecsly:benchmarks:start` and `ecsly:benchmarks:end` markers
// are generated; do not edit them by hand. Rationale: ADR 0005 (docs claim
// exactly what the artifacts prove — and never undersell them).

import 'dart:convert';
import 'dart:io';

const _startMarker =
    '<!-- ecsly:benchmarks:start — generated by tool/docs/sync_readme_benchmarks.dart; do not edit inside -->';
const _endMarker = '<!-- ecsly:benchmarks:end -->';

/// Curated presentation for scorecard metrics: artifact key -> (label, signal).
/// Metrics absent from the artifact are skipped; artifact metrics absent here
/// stay in the full scorecard only.
const _rootRows = <String, (String, String)>{
  'raw_query_chunk_ops_per_sec': (
    'Raw chunk iteration (30k entities)',
    'strongest hot query path',
  ),
  'mutable_query_iteration_ops_per_sec': (
    'In-place typed-column mutation (30k)',
    'zero-allocation component updates',
  ),
  'render_packet_extract_30k_ops_per_sec': (
    'Render-packet extract (30k)',
    'simulation to Float32 payload for hosts',
  ),
  'game_frame_20k_p95_micros': (
    '20k-entity game frame, p95',
    'update + extract + flush per frame',
  ),
  'query_iteration_100000_entities_ops_per_sec': (
    'Query at 100k entities',
    'flat throughput from 1k to 100k',
  ),
  'frame_rss_delta_bytes': (
    'RSS growth, repeated frames (15k)',
    'near-zero allocation in steady state',
  ),
};

const _coreRows = <String, (String, String)>{
  ..._rootRows,
  'query_iteration_ops_per_sec': (
    'Typed-column query (30k entities)',
    'extension-component iteration over two components',
  ),
  'game_frame_20k_p50_micros': (
    '20k-entity game frame, p50',
    'median frame-shaped ECS cost',
  ),
  'command_flush_ops_per_sec': (
    'Command flush (20k)',
    'deferred structural change application',
  ),
  'spawn_despawn_churn_ops_per_sec': (
    'Spawn/despawn churn (30k)',
    'frame-style entity lifecycle pressure',
  ),
  'event_send_ops_per_sec': (
    'Event send',
    'typed-data channel writes',
  ),
  'event_read_ops_per_sec': (
    'Event read',
    'cursor reads over the event channel',
  ),
};

final _repoRoot = File(Platform.script.toFilePath()).parent.parent.parent;

void main(List<String> args) {
  final check = args.contains('--check');
  final unknown = args.where((a) => a != '--check').toList();
  if (unknown.isNotEmpty) {
    stderr.writeln('Unknown argument: ${unknown.join(' ')}');
    stderr.writeln(
      'Usage: dart tool/docs/sync_readme_benchmarks.dart [--check]',
    );
    exit(64);
  }

  final artifact = _readArtifact();
  final failures = <String>[];

  final targets = <(String, Map<String, (String, String)>)>[
    ('README.md', _rootRows),
    ('core_packages/ecsly/README.md', _coreRows),
  ];
  for (final (relPath, rows) in targets) {
    final file = File('${_repoRoot.path}/$relPath');
    if (!file.existsSync()) {
      failures.add('$relPath: missing');
      continue;
    }
    final original = file.readAsStringSync();
    final block = _renderBlock(artifact, rows, core: relPath != 'README.md');
    final updated = _replaceBlock(relPath, original, block, failures);
    if (updated == null || updated == original) continue;
    if (check) {
      failures.add('$relPath: benchmark block is stale');
    } else {
      file.writeAsStringSync(updated);
      stdout.writeln('updated $relPath');
    }
  }

  // docs.json version variable must match the core pubspec version.
  final pubspecVersion = _corePubspecVersion();
  final docsJsonFile = File('${_repoRoot.path}/docs.json');
  if (pubspecVersion != null && docsJsonFile.existsSync()) {
    final docsJson = docsJsonFile.readAsStringSync();
    final decoded = jsonDecode(docsJson) as Map<String, Object?>;
    final variables = decoded['variables'];
    final current = variables is Map ? variables['version'] : null;
    if (current != pubspecVersion) {
      if (check) {
        failures.add(
          'docs.json: variables.version is $current, core pubspec is $pubspecVersion',
        );
      } else {
        final updated = docsJson.replaceFirst(
          RegExp(r'("variables":\s*\{\s*"version":\s*")[^"]*(")'),
          '\$1$pubspecVersion\$2',
        );
        docsJsonFile.writeAsStringSync(updated);
        stdout.writeln('updated docs.json variables.version');
      }
    }
  }

  if (failures.isNotEmpty) {
    stderr.writeln('Documentation drift detected:');
    for (final failure in failures) {
      stderr.writeln('  - $failure');
    }
    stderr.writeln(
      'Run `dart tool/docs/sync_readme_benchmarks.dart` to regenerate.',
    );
    exit(1);
  }
  stdout.writeln(check ? 'docs in sync' : 'done');
}

class _Artifact {
  _Artifact({
    required this.header,
    required this.metrics,
  });

  final Map<String, String> header;
  final Map<String, double> metrics;

  String get environmentLine {
    final machine = header['Machine'] ?? 'unknown machine';
    final cpu = header['CPU'];
    final memory = header['Memory'];
    final dart = (header['Dart'] ?? '').split(' ').first;
    final commit = header['Git commit'] ?? 'unknown';
    final generated = (header['Generated'] ?? '').split('T').first;
    final hardware = [
      if (cpu != null && cpu.isNotEmpty) cpu,
      if (memory != null && memory.isNotEmpty) memory,
    ].join(', ');
    return 'Median of 5 samples on $machine'
        '${hardware.isEmpty ? '' : ' ($hardware)'}, Dart $dart, '
        'commit `$commit`, $generated.';
  }
}

_Artifact _readArtifact() {
  final file = File(
    '${_repoRoot.path}/core_packages/ecsly/benchmark/results/latest.md',
  );
  if (!file.existsSync()) {
    stderr.writeln('Missing benchmark artifact: ${file.path}');
    exit(1);
  }
  final header = <String, String>{};
  final metrics = <String, double>{};
  for (final rawLine in file.readAsLinesSync()) {
    final line = rawLine.trim();
    final bullet = RegExp(r'^-\s+([^:]+):\s+`?([^`]*)`?$').firstMatch(line);
    if (bullet != null) {
      header[bullet.group(1)!.trim()] = bullet.group(2)!.trim();
      continue;
    }
    if (!line.startsWith('|') || line.contains('---')) continue;
    final cells = line
        .split('|')
        .map((c) => c.trim())
        .where((c) => c.isNotEmpty)
        .toList();
    if (cells.length < 4) continue;
    final key = cells[0].replaceAll('`', '');
    if (key == 'Metric') continue;
    final value = double.tryParse(cells[3].split(' ').first.replaceAll(',', ''));
    if (value != null) metrics[key] = value;
  }
  if (metrics.isEmpty) {
    stderr.writeln('No metrics parsed from ${file.path}');
    exit(1);
  }
  return _Artifact(header: header, metrics: metrics);
}

String _renderBlock(
  _Artifact artifact,
  Map<String, (String, String)> rows, {
  required bool core,
}) {
  final buffer = StringBuffer()
    ..writeln(_startMarker)
    ..writeln('| Metric | Result | Signal |')
    ..writeln('| --- | ---: | --- |');
  for (final entry in rows.entries) {
    final value = artifact.metrics[entry.key];
    if (value == null) continue;
    final (label, signal) = entry.value;
    buffer.writeln('| $label | ${_format(entry.key, value)} | $signal |');
  }
  buffer
    ..writeln()
    ..writeln(artifact.environmentLine)
    ..writeln()
    ..writeln(
      'Reproduce: `cd core_packages/ecsly && dart run benchmark/run.dart '
      '--limits --samples=5`.',
    );
  if (!core) {
    buffer.writeln(
      'Full scorecard: '
      '[`benchmark/results/latest.md`](core_packages/ecsly/benchmark/results/latest.md).',
    );
  }
  buffer.write(_endMarker);
  return buffer.toString();
}

String _format(String key, double value) {
  if (key.endsWith('_ops_per_sec')) {
    if (value >= 1e6) return '${(value / 1e6).toStringAsFixed(1)}M ops/s';
    if (value >= 1e3) return '${(value / 1e3).toStringAsFixed(0)}K ops/s';
    return '${value.toStringAsFixed(0)} ops/s';
  }
  if (key.endsWith('_micros')) return '${value.toStringAsFixed(0)} µs';
  if (key.endsWith('_bytes')) {
    if (value >= 1024 * 1024) {
      return '${(value / (1024 * 1024)).toStringAsFixed(1)} MiB';
    }
    if (value >= 1024) return '${(value / 1024).toStringAsFixed(0)} KiB';
    return '${value.toStringAsFixed(0)} B';
  }
  return value.toStringAsFixed(2);
}

String? _replaceBlock(
  String relPath,
  String original,
  String block,
  List<String> failures,
) {
  final start = original.indexOf(_startMarker);
  final end = original.indexOf(_endMarker);
  if (start < 0 || end < 0 || end < start) {
    failures.add('$relPath: missing ecsly:benchmarks markers');
    return null;
  }
  return original.replaceRange(start, end + _endMarker.length, block);
}

String? _corePubspecVersion() {
  final file = File('${_repoRoot.path}/core_packages/ecsly/pubspec.yaml');
  if (!file.existsSync()) return null;
  final match = RegExp(
    r'^version:\s*(.+)$',
    multiLine: true,
  ).firstMatch(file.readAsStringSync());
  return match?.group(1)?.trim();
}
